import Foundation
import ReadiumShared
@testable import ReadiumStreamer
import Testing
import TestSupport

/// The fixtures are generated by `Fixtures/audio/generate.sh`, which holds
/// their tags.
///
/// The expected metadata of each fixture is checked on its file, which is read
/// directly. `Sources` checks that the other resources give the same.
enum DefaultAudioMetadataReaderTests {
    struct MP4 {
        /// `faststart.m4b` holds its metadata at the start of the file.
        @Test(arguments: ["tagged.m4b", "faststart.m4b"])
        func readsTheAtoms(fixture: String) async throws {
            #expect(try await reader.read(fixture: fixture) == AudioMetadata(
                title: "Part One",
                album: "The Book",
                // In `tagged.m4b`, `©st3` is blank and the subtitle comes from
                // `----:SUBTITLE`. In `faststart.m4b`, it comes from `©st3`,
                // which has priority over another `----:SUBTITLE`.
                subtitle: "A Subtitle",
                // An MP4 value is not split on `/`.
                albumArtists: ["Jane Author/Jill Author"],
                artists: ["Jane Author/Jill Author", "Nora Narrator"],
                narrators: ["Nora Narrator/Ned Narrator"],
                composers: ["Carl Composer/Cleo Composer"],
                movementName: "The Movement",
                movementIndex: 3,
                // From `----:series`, after a `SERIES` atom with another mean.
                series: "The Saga",
                seriesPosition: 2.5,
                publishers: ["Acme Audio/Books"],
                date: "2021-03-04".dateFromISO8601,
                genres: ["Fantasy", "Adventure"],
                description: "A long description.",
                summary: "A summary.",
                comment: "A comment.",
                // The second value, `eng/deu`, is not a language.
                languages: ["fr"],
                isbn: "978-1-234-56789-7",
                sortAlbum: "Saga 2 - The Book",
                sortTitle: "Part 1",
                cover: Cover(data: fixtures.data(at: "cover.jpg"), mediaType: .jpeg),
                duration: 3,
                bitrate: 32,
                // From the chapter track. The Nero atom holds another title.
                chapters: [
                    Chapter(title: "Opening", start: 0, duration: 1),
                    Chapter(title: "Chapitre deux é", start: 1, duration: 1.5),
                    Chapter(start: 2.5, duration: 0.5),
                ]
            ))
        }

        @Test func readsTheNeroChaptersWithoutAChapterTrack() async throws {
            #expect(try await reader.read(fixture: "nero.m4b") == AudioMetadata(
                duration: 3,
                bitrate: 32,
                chapters: [
                    Chapter(title: "One", start: 0, duration: 1.5),
                    Chapter(title: "Two", start: 1.5, duration: 1.5),
                ]
            ))
        }
    }

    struct ID3 {
        @Test func readsTheID3v24Frames() async throws {
            #expect(try await reader.read(fixture: "tagged.mp3") == AudioMetadata(
                title: "Part 2",
                album: "The Book",
                subtitle: "A Subtitle",
                albumArtists: ["Jane Author"],
                // Only the first of the two values of the frame.
                artists: ["Jane Author"],
                narrators: ["Nora Narrator", "Ned Narrator"],
                composers: ["Carl Composer"],
                // No movement: `MVNM` and `MVIN` are not read.
                series: "The Saga",
                seriesPosition: 2.5,
                publishers: ["Acme Audio"],
                releaseDate: "2021-03-04".dateFromISO8601,
                // From `TDRC`, which has priority over `TYER`.
                date: "2020-01-02T10:20:00Z".dateFromISO8601,
                genres: ["Fantasy", "Adventure"],
                description: "A long description.",
                summary: "A summary.",
                // The `COMM` frame without a description, which follows a
                // technical one.
                comment: "A comment following the technical comment.",
                languages: ["fr", "en"],
                isbn: "9781234567897",
                sortAlbum: "Saga 2 - The Book",
                sortTitle: "Part 2",
                // The embedded front cover, which follows a linked front cover
                // and a back cover.
                cover: Cover(data: fixtures.data(at: "cover.png"), mediaType: .png),
                duration: 3,
                bitrate: 32,
                // The file lists them in another order.
                chapters: [
                    Chapter(title: "Opening", start: 0, duration: 1),
                    Chapter(title: "Chapitre deux é", start: 1, duration: 1.5),
                    Chapter(start: 2.5, duration: 0.5),
                ]
            ))
        }

        @Test func readsTheID3v23Frames() async throws {
            #expect(try await reader.read(fixture: "tagged-v23.mp3") == AudioMetadata(
                title: "Part 3",
                albumArtists: ["Jane Author", "Jill Author"],
                artists: ["Jane Author", "Nora Narrator"],
                composers: ["Nora Narrator", "Ned Narrator"],
                publishers: ["Acme Audio", "Other Press"],
                // From `TYER`.
                date: "2021".dateFromISO8601,
                genres: ["Fantasy"],
                languages: ["en", "fr"],
                // The only picture, which is not a front cover and is
                // declared as `image/jpg`.
                cover: Cover(data: fixtures.data(at: "cover.jpg"), mediaType: .jpeg),
                duration: 3,
                bitrate: 32
            ))
        }

        @Test func bitrateIsUnknownWithoutAXingHeader() async throws {
            #expect(try await reader.read(fixture: "noxing.mp3") == AudioMetadata(duration: 3))
        }

        /// AVFoundation gives no chapter when a `CTOC` frame lists another
        /// one.
        @Test func readsNoChapterOfANestedTableOfContents() async throws {
            #expect(try await reader.read(fixture: "nested-toc.mp3") == AudioMetadata(
                title: "Nested",
                duration: 3,
                bitrate: 32
            ))
        }
    }

    struct Untagged {
        @Test func readsTheDurationOnly() async throws {
            #expect(try await reader.read(fixture: "untagged.wav") == AudioMetadata(duration: 1))
        }
    }

    struct WithoutCover {
        @Test(arguments: [Source.file, .memory])
        func readsEverythingButTheCover(source: Source) async throws {
            var expected = try await reader.read(fixture: "tagged.m4b", from: source)
            try #require(expected.cover != nil)
            expected.cover = nil

            #expect(try await reader.read(fixture: "tagged.m4b", from: source, includesCover: false) == expected)
        }
    }

    /// Resources which are not files are read through a resource loader.
    struct Sources {
        @Test(
            arguments: ["tagged.m4b", "faststart.m4b", "nero.m4b", "tagged.mp3", "tagged-v23.mp3", "nested-toc.mp3", "noxing.mp3", "untagged.wav"],
            [Source.memory, .entry(.minizip), .entry(.zipFoundation)]
        )
        func readsTheSameMetadataAsFromTheFile(fixture: String, source: Source) async throws {
            let expected = try await reader.read(AudioMetadataRequest(fixture: fixture)).get()

            #expect(try await reader.read(AudioMetadataRequest(fixture: fixture, from: source)).get() == expected)
        }

        /// The fixtures fit in the first request of AVFoundation. This
        /// resource of 8 MB is delivered slowly, so AVFoundation usually
        /// abandons that request to ask for the `moov` atom at its end.
        @Test func readsTheMetadataAtTheEndOfALargeResource() async throws {
            let expected = try await reader.read(AudioMetadataRequest(fixture: "tagged.m4b")).get()
            let resource = StubResource(.serving(m4bFixturePadded(toLength: 8 << 20)))
            // The abandoned streams end as soon as they are cancelled.
            resource.releaseCancelledStreams(after: 0)

            #expect(try await reader.read(AudioMetadataRequest(resource: resource, format: .mp4)).get() == expected)
        }
    }

    /// A read through a resource loader leaves no stream of the resource
    /// behind it. The streams of the resources end a moment after their
    /// cancellation.
    struct Streams {
        @Test func haveEndedAfterARead() async throws {
            // Given a resource which takes over a second to deliver, far
            // more than the read: a stream is cancelled, by AVFoundation
            // abandoning its request or by the end of the read.
            let resource = StubResource(.serving(WAV.silence(duration: 1200)))
            let reading = Task { await reader.read(AudioMetadataRequest(resource: resource, format: .wav)) }
            #expect(await resource.wait(for: .cancelled))
            resource.releaseCancelledStreams(after: 0.1)

            #expect(try await reading.value.get().duration == 1200)
            #expect(resource.activeStreamCount == 0)
        }

        @Test func haveEndedAfterACancelledRead() async {
            // Given a read waiting for a stream of its resource.
            let resource = StubResource(.holding)
            let reading = Task { await reader.read(AudioMetadataRequest(resource: resource, format: .mp3)) }
            #expect(await resource.wait(for: .started))

            resource.releaseCancelledStreams(after: 0.1)
            reading.cancel()

            #expect(await reading.value.readFailure == .cancelled)
            #expect(resource.activeStreamCount == 0)
        }
    }

    struct Failures {
        /// Ogg is no example of a format which AVFoundation does not declare:
        /// iOS 27 declares it, and reads the Ogg files holding Opus audio.
        ///
        /// A format without a media type, as `Format.null`, has no content
        /// type to serve a resource with.
        @Test(
            arguments: [
                (Format.mp3, ReadFailure.decoding),
                (Format.webm, ReadFailure.resourceNotSupported),
                (Format.null, ReadFailure.resourceNotSupported),
            ],
            [Source.file, .memory]
        )
        func defectiveResourceFailsWithDecodingOnlyForAFormatDeclaredByAVFoundation(expectation: (Format, ReadFailure), source: Source) async throws {
            let (format, expected) = expectation

            let result = try await reader.read(AudioMetadataRequest(fixture: "garbage.mp3", from: source, format: format))

            #expect(result.readFailure == expected)
        }

        @Test func missingFileFailsWithAnAccessError() async throws {
            let result = try await reader.read(AudioMetadataRequest(fixture: "missing.mp3"))

            #expect(result.readFailure == .fileNotFound)
        }

        /// The length of the resource is known, so the error is the one of a
        /// stream requested by AVFoundation.
        @Test func failingStreamFailsWithItsError() async {
            let resource = StubResource(.failing(.access(.fileSystem(.fileNotFound(nil)))))

            let result = await reader.read(AudioMetadataRequest(resource: resource, format: .mp3))

            #expect(result.readFailure == .fileNotFound)
        }

        @Test func failingPropertiesFailWithTheirError() async {
            let resource = StubResource(.holding, properties: .failure(.access(.fileSystem(.fileNotFound(nil)))))

            let result = await reader.read(AudioMetadataRequest(resource: resource, format: .mp3))

            #expect(result.readFailure == .fileNotFound)
        }

        /// The MP3 files of `audiotest.zab` are compressed.
        @Test(arguments: [ZIPOpener.minizip, .zipFoundation])
        func compressedArchiveEntryIsNotSupported(opener: ZIPOpener) async throws {
            let entry = try await opener.entry("Test%20Audiobook/Latin.mp3", of: Fixtures().url(for: "audiotest.zab"))

            let result = await reader.read(AudioMetadataRequest(resource: entry, format: .mp3))

            #expect(result.readFailure == .resourceNotSupported)
        }

        @Test func cancelledTaskFailsWithCancelled() async throws {
            let request = try await AudioMetadataRequest(fixture: "tagged.m4b")
            let task = Task {
                withUnsafeCurrentTask { $0?.cancel() }
                return await reader.read(request)
            }

            #expect(await task.value.readFailure == .cancelled)
        }
    }

    /// How a fixture is given to the reader.
    enum Source {
        /// A file, which is read directly.
        case file
        /// A resource in memory.
        case memory
        /// An entry of `stored.zip`, which is not compressed.
        case entry(ZIPOpener)
    }

    /// What opens a ZIP archive.
    enum ZIPOpener {
        case minizip
        case zipFoundation
    }

    /// A failure of the reader without its underlying error, to compare it.
    enum ReadFailure: Equatable {
        case resourceNotSupported
        case decoding
        case fileNotFound
        case cancelled
        case other(String)
    }
}

// MARK: - Helpers

private typealias Chapter = AudioMetadata.Chapter
private typealias Cover = AudioMetadata.Cover
private typealias ReadFailure = DefaultAudioMetadataReaderTests.ReadFailure
private typealias Source = DefaultAudioMetadataReaderTests.Source
private typealias ZIPOpener = DefaultAudioMetadataReaderTests.ZIPOpener

private let reader = DefaultAudioMetadataReader()
private let fixtures = Fixtures(path: "audio")

private extension DefaultAudioMetadataReader {
    /// Reads the given audio fixture, then rounds the durations to a tenth of
    /// a second and the bitrate to a kbps.
    ///
    /// The durations of the fixtures depend on their encoding: a file of
    /// three seconds reports from 2.98 to 3.03 seconds.
    func read(fixture: String, from source: Source = .file, includesCover: Bool = true) async throws -> AudioMetadata {
        var metadata = try await read(AudioMetadataRequest(fixture: fixture, from: source, includesCover: includesCover)).get()
        metadata.duration = metadata.duration?.roundedToTenth
        metadata.bitrate = metadata.bitrate?.rounded()
        metadata.chapters = metadata.chapters.map { chapter in
            var chapter = chapter
            chapter.start = chapter.start.roundedToTenth
            chapter.duration = chapter.duration?.roundedToTenth
            return chapter
        }
        return metadata
    }
}

private extension AudioMetadataRequest {
    /// Creates a request to read the given audio fixture from `source`.
    ///
    /// - Parameter format: The format sniffed from the file extension of the
    ///   fixture when nil.
    init(fixture: String, from source: Source = .file, format: Format? = nil, includesCover: Bool = true) async throws {
        let resource: Resource = switch source {
        case .file: FileResource(file: fixtures.url(for: fixture))
        case .memory: DataResource(data: fixtures.data(at: fixture))
        case let .entry(opener): try await opener.entry(fixture, of: fixtures.url(for: "stored.zip"))
        }
        let fileExtension = fixtures.url(for: fixture).pathExtension

        try self.init(
            resource: resource,
            format: format ?? #require(AudioFormatSniffer().sniffHints(FormatHints(fileExtension: fileExtension))),
            includesCover: includesCover
        )
    }
}

private extension ZIPOpener {
    /// Returns the entry at `href` in the given ZIP archive.
    func entry(_ href: String, of archive: FileURL) async throws -> Resource {
        let opener: ArchiveOpener = switch self {
        case .minizip: MinizipArchiveOpener()
        case .zipFoundation: ZIPFoundationArchiveOpener()
        }
        let container = try await opener.open(
            resource: FileResource(file: archive),
            format: Format(specifications: .zip, mediaType: .zip, fileExtension: "zip")
        ).get().container
        return try #require(container[AnyURL(string: href)!])
    }
}

/// Returns `tagged.m4b` grown to `length` bytes with zeros at the end of its
/// `mdat` atom. Its `moov` atom, which holds the metadata, stays at the end of
/// the file, so the offsets it holds stay valid.
private func m4bFixturePadded(toLength length: Int) -> Data {
    var data = fixtures.data(at: "tagged.m4b")
    // An atom starts with its size on four bytes, followed by its type.
    let mdat = data.range(of: Data("mdat".utf8))!.lowerBound - 4
    let moov = data.range(of: Data("moov".utf8), options: .backwards)!.lowerBound - 4
    let padding = length - data.count

    data.insert(contentsOf: Data(count: padding), at: moov)
    data.replaceSubrange(mdat ..< mdat + 4, with: withUnsafeBytes(of: UInt32(moov - mdat + padding).bigEndian) { Data($0) })
    return data
}

private extension Format {
    static let mp3 = Format(specifications: .mp3, mediaType: .mp3, fileExtension: "mp3")
    static let mp4 = Format(specifications: .mp4, mediaType: .mp4, fileExtension: "mp4")
    static let wav = Format(specifications: .wav, mediaType: .wav, fileExtension: "wav")
    static let webm = Format(specifications: .webm, mediaType: .webmAudio, fileExtension: "webm")
}

private extension Result<AudioMetadata, AudioMetadataReadError> {
    var readFailure: ReadFailure? {
        switch self {
        case .success: nil
        case .failure(.resourceNotSupported): .resourceNotSupported
        case .failure(.reading(.decoding)): .decoding
        case .failure(.reading(.access(.fileSystem(.fileNotFound)))): .fileNotFound
        case .failure(.reading(.cancelled)): .cancelled
        case let .failure(error): .other(String(describing: error))
        }
    }
}

private extension Double {
    var roundedToTenth: Double {
        (self * 10).rounded() / 10
    }
}
